import{_ as e,c as p,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"易纂言卷八","description":"易纂言 - 易纂言卷八","frontmatter":{"title":"易纂言卷八","description":"易纂言 - 易纂言卷八"},"headers":[],"relativePath":"classics/zuanyan/009.md","filePath":"classics/zuanyan/009.md"}'),n={name:"classics/zuanyan/009.md"};function r(c,a,_,i,o,l){return t(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="易纂言卷八" tabindex="-1">易纂言卷八 <a class="header-anchor" href="#易纂言卷八" aria-label="Permalink to “易纂言卷八”">​</a></h1><p>欽定四庫全書</p><p>元吳澄撰</p><p>八卦成列，象在其中矣。因而重之，爻在其中矣。剛柔相推，變在其中矣；繫辭焉而命之，動在其中矣。吉凶悔吝者，生乎動者也。 八卦成列，謂乾一、兌二、離三、震四、巽五、坎六、艮七、坤八相次也。象，謂文王所名之卦。在其中者，謂包含於其中也。因而重之，謂因八卦而重之為六十四也。爻，謂周公所繫之辭。變者，蓍之變。命，猶名也。動者，人之動。已有八卦之時，猶未有六十四卦之名也。已有重卦之時，猶未有三百八十四爻之辭也。剛柔二畫，雖能相推變化，然蓍未變則未有九、六也。繫辭雖名為吉為兇，然人未動則未有吉、兇也。雖未有之，而其理已具，故曰在其中矣。吉凶悔吝，因人之動而後有。周子曰：吉一而已，動可不慎乎？澄謂：「此承前篇卒章，言蓍卦之象、辭、變、佔。曰在其中者凡四：一象、二爻、三變、四動。爻者，辭也。動則有吉凶悔吝之佔焉。前篇動者尚其變，而此以動屬佔者，動因變而得佔也。 剛柔者，立本者也；變通者，趣時者也。」 剛柔之畫，其體一定，如木本之植立，因蓍之變，其用相通，隨時所遇，趣而就之，剛或化柔，柔或化剛也。此承「剛柔相推，變在其中」之語，而言蓍之變。 吉凶者，貞勝者也。天地之道，貞觀者也；日月之道，貞明者也。天下之動，貞夫一者也。 貞，謂正主之也。吉凶二佔，正主於一勝。吉勝則無兇，兇勝則無吉，非如悔吝之可吉可兇也。觀，猶示也。因吉凶之正主於勝，遂言天地之文理正主於示人；日月之往來正主於明照；而天下人事之動，則正主於一，而不可以二。不吉則兇，不兇則吉，所謂貞勝也。此承「吉凶悔吝生乎動」之語，而言蓍之佔。 夫乾，確然示人易矣。夫坤，隤然示人簡矣。爻也者，效此者也。象也者，像此者也。 「乾」謂天，「坤」謂地，非卦名也。確，剛健貌。隤，柔順貌。天地之「貞觀」者，天則剛健而示人以易，地則柔順而示人以簡。周公之爻，文王之象，則亦效像天地而示人以易簡也。此承「象在其中」、「爻在其中」之語，而言卦之爻與象。 爻象動乎內，吉凶見乎外，功業見乎變，聖人之情見乎辭。 內，謂易書之內；外，謂易書之外。爻象無非示人以動而趨吉之理，然其動在乎易書之內，實未嘗有動之事也。人之動如是而吉，不如是而兇，則著見於人事，而在乎易書之外矣。以蓍之變，決其嫌疑，定其猶豫，而勇於趨事，則功業之成，皆因蓍之變而著見也。以上言辭、言象、言吉凶之佔、言見乎變，四者備矣。而又以一句結之，謂聖人與民同患之情，皆於易而著見，此辭字兼彖爻言也。聖人之道四，而獨歸重於辭，蓋此篇為繫辭之傳故也。</p><p>傳六之一章，凡百四十六字。趣，立樹切。勝，繩證切。觀，古喚切。夫，音扶。確，苦各切。易，以豉切。隤，同捸切。見，經電切。諸本皆至下章「禁民為非曰義」為一章。今案：「天地之大德曰生」與此文不相屬，當為下章之首。屬，之慾切。 天地之大德曰生，聖人之大寶曰位。何以守位曰人，何以聚人曰財。理財正辭，禁民為非曰義。 生生不已者，天地之大德。然天地生物生人，又生與天地合德之聖人，命之居君師之位，為人物之主，而後能使天地之所生得以各遂其生也。苟或但有其德而無其位，則亦不能相天地而遂人物之生，故位為聖人之大寶。大寶，謂大可貴重。守，謂保有之，必得眾人之歸向，乃能保有君師之位。聚，謂養之而使蕃盛眾多。財者，天地所生之物，以養天地所生之人，故聚人以財也。理，謂以道取而用之。理財必正其辭，謂取其所當取可取，言之而無悖無愧者。禁，謂防制之。蓋財者，民之所同欲，爭盜之所由起，必設法令以禁其為非，使之不敢爭，不敢盜。義者，事理之宜。理財之所宜理，禁民之所不宜為，夫是之謂義。以下言五聖人之製作，皆聚人理財之事。 古者包犧氏之王天下也，仰則觀象於天，俯則觀法於地，觀鳥獸之文與地之宜，近取諸身，遠取諸物，於是始作八卦，以通神明之德，以類萬物之情。 包犧氏，大昊也。氣之有文者曰象，形之有理者曰法。漢書藝文志相地為形法家。天有雷、風、日、月。雷風，氣也。日月，象也。言象可以兼氣。地有水、火、山、澤，水火，質也。山澤，形也。言形可以兼質。鳥獸之文，謂動物。地之宜，謂植物。身，就人而言。物，該服食器用而言。通，同之也。神明，天地之氣象形質，妙而叵測，顯而可見者也。德，若「健」、「順」、「動」、「入」、「陷」、「麗」、「止」、「說」，及鼓之，散之，「潤之」，「烜之」之屬，類似之也。「萬物」，凡動植人器皆是。「情」，猶言其意義也。羲皇觀於天地，觀於動植，近取遠取，洞見兩間自然之易，乃畫奇耦二畫，交互成八卦以象之。而天地萬物悉不外是。故與其德同，而與其情無不相似也。天開地闢之後，不知其幾萬年矣。而洪荒樸略，未有文字。至羲皇始畫八卦，實肇人文之端，故將言製作之事，而首言此也。 作結繩而為網罟，以佃以漁，蓋取諸離。 以散絲散麻絆緊而合之曰「結」，結之以為繩也。網以取獸曰「佃」。罟以取魚曰「漁」。或曰「網」罟通用，上古之時，已有結繩矣。作之而為網罟者，羲皇也。或曰結繩而治，亦自羲皇始。「結繩」、網罟二事，結繩以防欺詐，因以為網罟而佃漁也。二說未詳孰是。「蓋」者，不敢決定之辭。聖人非必模仿此卦以制此器，其象相類爾。又此時未有重卦之名，借後本所立卦名言之，故不決定其辭，而曰「蓋」。「離」謂「重離」。「重離」兩目相承，邊實中虛，為物所麗，結繩網罟之象。人無爪牙，不能敵獸之猛。羲皇以前，獸每食人。既有網罟之後，人始能取魚獸以食之，而免為獸所食。大哉，聖人之仁乎！ 包犧氏沒，神農氏作，斲木為耜，揉木為耒，耒耨之地，以教天下，蓋取諸益。 神農氏，炎帝也。斲，謂削而銳之。耜者，耒首。揉，謂揉而曲之。耒者，耜柄。教天下者，古未有粒食，神農始教民稼穡者也。益之二三四，互坤，地也。上巽二陽，象耒之自地上而入。下震一陽，象耜之在地下而動也。 日中為市，致天下之民，聚天下之貨，交易而退，各得其所，蓋取諸噬嗑。 案，周官有三市，此獨言日中者，或創市之初，惟用日中，后王乃增朝夕二市與？噬嗑上離，日中之象。離中虛，可藏貨，市之象。震動而前，致民之象。震二柔畫，為民。離明，萬物相見，聚貨之象。離二剛畫，富實貨也。一剛一柔相間，有相交相易之象。退，謂交易既畢而歸其家。各得其所，謂以其所有，易其所無，而歸各得以遂其願，濟其所用也。 神農氏沒，黃帝、堯、舜氏作，通其變，使民不倦；神而化之，使民宜之。易窮則變，變則通，通則久。 黃帝，軒轅氏。堯，陶唐氏。舜，有虞氏也。「通其變」者，通其所當變之事，使不至於窮也。變而無跡曰化。上古之時，民與禽獸無異，有網罟而鮮食者，有耒耜而得艱食者。艱鮮既奏，而又為市以質，遷其有無，則與禽獸稍異矣。然民用之未備者猶多也。風氣漸開，不可如樸略之世，此窮而當變也，變之則通而不窮矣。其能使民喜樂不倦者，以其通之之道神妙不測，變而不見其跡，使於民而民皆宜利之故爾。凡易之道，窮則必變而通之，然後可以久而無弊。黃帝、堯、舜之通其變者，易之道也。九事皆黃帝時，而並言堯、舜者，肇始於黃帝，而極備於堯、舜也。不言少昊、顓頊、帝嚳者，承黃帝之後，因之而無所損益也。 黃帝、堯、舜垂衣裳而天下治，蓋取諸乾坤。 「衣」，上體之服。「裳」，下體之服。上古以禽獸、羽毛、草木華葉蔽其體，至此始以絲麻為衣裳也。上衣下裳，如天尊地卑，上下分定，故天下治。乾畫奇，象衣之縫合為一。坤畫耦，象裳之前後殊為二。 刳木為舟，剡木為楫，舟楫之利，以濟不通，蓋取諸渙。 刳木者，刳空其中為舟以浮水。剡木者，剡薄其端為楫以運舟。水所阻隔，道路不通，則以舟楫渡而濟之也。「渙」巽木，在「坎」水之上。二三四五上，舟虛之象。初耦二「楫」，運於舟後之象。 服牛乘馬，引重致遠，以利天下，蓋取諸隨。 服者，以軛加其項，而使之引重。載乘者，以衡加其背，而使之致達道。隨下震自坤而變坤為牛，一奇畫在後者，象所引之重物也。上兌自乾而變，乾為馬，一耦在前者，象前路開通無礙，而可以致遠也。 重門擊柝，以待暴客，蓋取諸豫。 郭門、城門為重門。「擊拆」，所以警夜而防奸盜也。暴客，謂奸盜。豫前二耦畫，重門之象。九四一奇畫而動，體擊柝於門內之象。坤三畫在下，民安居於內，而無暴客侵陵之象。 斷木為杵，掘地為臼，臼杵之利，萬民以濟，蓋取諸小過。 杵以舂，臼以容，用之搗去粟殼而得米，其利便萬民，亦猶渡水之得濟也。小過橫而觀之，中二奇畫象木杵，內外四耦畫象地臼。 弦木為弧，剡木為矢，弧矢之利，以威天下，蓋取諸睽。 弧，木弓也。兵器不一，弓矢所及者遠，為長兵威天下者，示有警備而使之畏也。坎象弧者，中弣強而上下兩弰弱也。離象天者，前鏃後栝實、中笴虛也。暌三四五互坎，弧象；二三四互離，及上體之離，皆矢象。 上古穴居而野處，後世聖人易之以宮室，上棟下宇，以待風雨，蓋取諸大壯。 上古，謂黃帝以前。穴居土中，營窟也。野處木杪，橧巢也。「後世聖人」，謂黃帝、堯、舜也。外垣四同曰「宮」，戶牖之內曰「室」。「棟」，檁之上隆者。「宇」，椽之下垂者。有棟宇而成屋，則可以障風蔽雨。大壯下四剛，棟承上而隆之象；上二柔，宇覆下而垂之象。 古之葬者，厚衣之以薪，葬之中野，不封不樹，喪期無數，後世聖人易之以棺槨，蓋取諸大過。 「厚衣之以薪」，謂以薪承藉其下而置屍焉，復以薪蓋覆於其上也。「中野」，野中也。「不封」，不封土為墳也。「不樹」，不樹木以識也。「喪期無數」，哀盡則止，無卒哭、祔、練、祥、禫之日數也。「棺」，內棺；「槨」，外棺也。凡奇畫為長，耦畫為短。大過中四長畫；九二，棺底木也；九三、九四，棺兩傍木也；九五，棺蓋木也。初、上二短畫，上六，棺前端木也；初六，棺後端木也。 上古結繩而治，後世聖人易之以書契，百官以治，萬民以察，蓋取諸夬。 「結繩」，說者謂民淳事簡，結繩以為信，大事大其繩，小事小其繩，以識別也。「書」，以刀筆畫木簡為文字也。「契」，以木刻一、二、三、四之畫，而中分之，各執其一，合之以為信也。「契」者，書之始也。契惟以畫記數而已，書則有指事、象形之變，有文字則可以治百官之事，察萬民之情矣。書契自一畫、二畫、三畫、四畫始，至五畫則為又，蓋至五而窮也，窮則變。夬有五奇畫，象書契之一、二、三、四、五，至六則變矣。故上畫耦者，奇之變也，又象契之上端分為二之處。十三卦之製作，自畫卦而始，至書契而終。蓋萬世文字之祖，肇於畫卦，而備於書契也。 是故易者，象也。象也者，象也。 此章之首第一節，總敘以起下文。自「包犧」至「書契」十四節，言製作之事，而以是故總結之。謂易卦皆器物之象，象者，像似之義。聖人制器，皆與卦象合也。 彖者，材也。爻也者，效天下之動者也。 既結一章之意矣，因象而及於辭，謂文王彖辭以六畫之象而論一卦之材質，周公爻辭以一畫之象而效人所作為之事。 是故吉凶生而悔吝著也。 又以是故結上文二句，謂彖、爻如此，故生出吉凶而使人趨避，著明悔吝而使人警悟也。</p><p>傳六之二章，凡四百二十九字。「守位曰人」，舊本「人」作「仁」。陸氏曰：王肅、卞伯、王、桓玄、明僧紹作人。耒耜，舊本「耜」作「耨」。晁氏曰：「王昭素雲：諸本或作耜，乃合上文。」澄謂傳寫者訛右傍以字為「辱」也。今正之。「通則久」下，舊本有「是以自天祐之，吉無不利」十字。系文言傳釋大有上九爻辭，錯簡重出。「以濟不通」下，舊本有「致遠以利天下」六字。陸氏曰：「一本無。」今案：此六字見下文，羨文重出也。包，白交切。王於況切。柝天作切。厚衣於既切。注相天地息亮切。後「相地」同。夫是音扶。叵平可切。止說音曰。烜沉遠切。合之音合。二市與音餘。相間居限切。喜樂音洛。分定封問切。重載親採切。舂黍容切。弣封古切。弰新巢切。鏃子本切。笴見汗切。僧音曾。垣音袁。檁林錦切。藉晴夜切。置音至。復以扶後切。覆孚後切。以識音志。後「識別」同。潭汀坎切。別彼列切。 陽卦多陰，陰卦多陽，其故何也？陽卦奇，陰卦耦。其德行何也？陽一君而二民，君子之道也；陰二君而一民，小人之道也。 陽卦，震、坎、艮也，皆一陽二陰，陰多於陽。陰卦，巽、離、兌也，皆一陰二陽，陽多於陰。故者，其跡之粗；德行者，其理之精。先粗後精，兩設問而兩答之也。陽卦數奇多陰，則一奇二偶，合成五數；陰卦數耦多陽，則一耦二奇，合成四數。數分奇耦，以答其故之問。陽畫為君，陰畫為民。陽卦一君統二民，寡能治眾，主必致一，得理之正，為君子之道。陰卦一民事二君，土無二王，物不兩大，非理之正，為小人之道。道分君子小人，以答其德行之問。 乾坤，其易之門邪？乾，陽物也。坤，陰物也。陰陽合德，而剛柔有體，以體天地之撰，以通神明之德。 上文既言六子之卦，此乃言六子自乾坤而生也。易，謂六子，以奇耦相易而成卦，故曰「易」。乾坤者，六子之所從出，故曰「門」。「物」，猶言畫也。射禮：畫於地者亦曰物。乾三畫皆陽，故曰「陽物」。坤三畫皆陰，故曰「陰物」。乾，陽之德；坤，陰之德，交互相合，以生六子。而震、坎、艮，有一剛二柔之體，巽、離、兌，有一柔二剛之體。此八卦者，與天地神明一也，故曰「體」曰「通」。「體」，謂以之為體也。「撰」，猶言所為也。「體天地之撰」，以卦象言。「通神明之德」，以卦德言。 其稱名也，雜而不越，於稽其類，其衰世之意邪？ 此又言六十四卦自八卦而生也。「名」，謂重卦之名。「離」，謂不一。「越」，過也。「於」，嘆辭。「稽」，推考也。文王所稱五十六卦之名，雖其義不一，而皆不過自八卦中出。嘆其推考重卦兩體，與八卦所象相類而立名之意。見其遭遇衰世，憂患危懼，是以推考如是其精微也。 夫易彰往而察來，而微顯闡幽，開而當名辨物，正言斷辭，則備矣。 以上三節，首言六卦之體，次言六卦本乎二卦而為八，又言重卦本乎八卦而為六十四。此以下總上三節而言文王之彖辭。「彰往」，即「藏往」也，謂明於天之道，而彰明已往之理。「察來」，即「知來」也，謂察於民之故，而察知未來之事。「微顯」，即「神德行」也，謂以人事之顯，而本之於天道，所以微其顯。「闡」者，闡而顯之也。「闡幽」，即「顯道」也，謂以天道之幽，而用之於人事，所以闡其幽。上篇之「藏往」、「知來」、「顯道」、「神德行」，兼蓍而言，此則專以卦而言也。開明名卦之意，而使當其名。辨別陰陽之物，而正言其佔。「夫易」以下諸義，自文王斷以彖辭之後，則皆具備矣。朱子曰：「而微顯」，恐當作「微顯而」。「開而」之「而」，亦疑有誤。 其稱名也小，其取類也大。其旨遠，其辭文，其言曲而中，其事肆而隱。因貳以濟民行，以明失得之報。 「小」，謂其義專而狹。「大」，謂其義泛而廣。「旨」，意也。「文」，謂修節而不質直。「曲」，謂一偏而不該徧。「中」，如居中而四外皆通。「肆」，謂縱而不拘。「隱」，謂晦而不顯。彖首所稱卦名，如上雲下雷，則名為屯；上山下泉，則名為蒙。但就本卦二體之象而生名，故曰小。彖中所取象類，如類動物，則有虎尾、豚魚、飛鳥、小孤之屬；類用物，則有盥薦、二簋、羸瓶、匕鬯之屬。泛及天下諸物之形而比類，故曰大。稱名之義雖小，而其旨則遠，謂推索而無窮盡也。取類之義雖大，而其辭則文，謂假託而不質言也。小者雖偏曲而局於一方，然旨之遠則中而可旁通也。大者雖縱肆而徧於諸物，然辭之文則隱而不顯露也。貳謂疑而不決，用筮以佔，而彖辭為決所疑，則行事之果如渡水之得濟，故曰「濟民行民於行事之失得未能明也」。以彖辭而知如此為得而行之則有吉報，如彼為失而行之則有兇報，故曰「明失得之報」。或謂此一節蓋論彖、爻。夫取類之大，辭之文，事之肆而隱，爻辭亦然，而此則專為彖辭言也。</p><p>傳六之三章，凡百六十二字。「小人之道也」下，舊本有文言傳錯簡，釋鹹九四、困六三、解上六、噬嗑初六、上六、否九五、鼎九四、豫六二、復初九、損六三、益上九爻辭十一節間隔之，故與乾坤其易之門不相屬，遂於「乾坤」上加「子曰」字，而分為別章。今定錯簡歸文言傳，刪去「子曰」字，而此章複合為一。德行，下孟切，後「民行」同。撰，士免切。於，音烏。夫，音扶。斷，東亂切。中，如字。注索，悉革切。為決，雲偽切，後「為彖」同。夫微顯，音扶。 易之興也，其於中古乎？作易者，其有憂患乎？ 中古，謂文王時。羲皇之易有畫而已，三畫之卦雖有名，而六畫之卦未有名，文王始名六畫之卦而系之以辭，易道幾微而至此復興也。卦名及辭皆前所未有，故不雲述而云作。作易在羑里時，故云其有憂患乎？蓋於其名卦而知其有憂患也。下文舉九卦之名，以見其憂患之意。 是故履，德之基也；謙，德之柄也；復，德之本也；恆，德之固也；損，德之修也；益，德之裕也；困，德之辨也；井，德之地也；巽，德之制也。 履，踐行也。基，如築土之下址，積累之所始也。謙，恭讓也。柄，所執持者也。復，反也，孟子謂君子必自反也，行有不得者，反求諸已，如木之反也。本，歸根也。恆，常久也。固，謂常守而不變也。損者，減損，謂消除其私慾也。修，謂完補其闕也。益者，增益，謂充長其善端也。裕如，加厚其衣也。困，阨窮也。辨者，識之明，孟子謂人之德慧術智存乎疢疾，因身之困而心識開明也。井不動而及物之惠普徧，猶地之靜而成物之功廣博。巽者，柔順卑下以入，則無處而不可入，如利刀之裁製布帛，隨其長短而裁之，無不如意也。始之以實踐，繼之以自謙，人不我是而自反，已之所守必有常，損其不善益其善，雖處困而識愈明，身不可動而不忘及物，柔順卑下，無入而不自得。此九字之義，皆處憂患之道也。 履和而至；謙尊而光；復小而辨於物；恆雜而不厭；損先難而後易；益長裕而不設；困窮而通；井居其所而遷；巽稱而隱。 上文初陳九卦之名，取其字義而已。此再陳，乃取卦義。項氏曰：「釋卦之兩體九句，皆以相反成文。」朱子曰：「如書之九德。」澄案：和謂兌之說，至謂乾之健。蓋雖與物無乖，而行必造極也。鄉原之閹然媚世，而不可入堯舜之道，則履之和而不至者。尊謂坤地之卑而尊之，使居艮上。光謂艮山雖下於坤，而自不失其為高。已處人下，疑若晦昩而不光。然謙則雖尊他人而已亦光也。小謂震。一陽之動。辨於物謂珅眾陰之順。一陽之復甚微，猶君子之自反，所操甚約也。然陽復於內雖微，而陰順於外則眾，猶君子一自反而橫逆者皆順，非明於接物不能也。「雜」謂其事不一，震雷之時復一鳴似之。「不厭」如言學不厭，巽風之無日不有似之。行事不一，而終終不厭倦，所以為恆也。「先難」謂方損之初，如浚兌澤於下，而畚土以上也。「後易」謂既損之後，如艮山之靜止，而受土以成其高也。「長裕」謂日益。「設」謂施為之虛假，如設使、設或之說。揠苗而長之，其苗非實有長裕也，虛假所為爾。震雷之聲，則實能助益巽風之勢，而不虛假也。「窮」，謂兌澤涸於上。「通」謂坎水流於下。或謂彖傳之險而說，亦窮而通之義。彼蓋合上下二德，以釋「困亨」，與此不同也。「居其所」，謂巽之二陽在下體，水之在井中者也。「遷」謂坎之一陽在上體，水之汲而上以及物者也。「稱」，謂巽二陽在陰之前，二陽體鈞，其重不偏，如稱物之平。「隱」謂巽一陰入陽之內，為卦之主，以事二君，而人莫知其所以能入二陽之故。履、復、損、井，取義以下體為先。謙、恆、益、困，取義以上體為先。巽八純重卦，但就一體取二義，而二體皆然。 履以和行，謙以制禮，復以自知，恆以一德，損以遠害，益以興利，困以寡怨，井以辯義，巽以行權。 此章三陳九卦，先後有淺深。初陳雜舉卦名，而每字之下，先就人身言之，以明其字義，未及卦義也。再陳，乃於卦名之下，說上下二體之義；三陳，則卦字名，一字之中包含上文所說卦體二義，非專指卦名一言也。「以」，猶象傳「君子以」之「以」，謂取此卦之義，用之於人事也。踐行之履，在人為德之基，故名下兌上乾之義曰「履」。其義兌和而乾至，人則以此履卦之義而和行。和行，謂所行無乖忤也。恭讓之謙，在人為德之柄，故名上坤下艮之卦曰「謙」。其義坤尊而艮光，人則以此謙卦之義而「制禮」。禮者，恭敬退讓，自卑而尊人；制禮，謂製為儀則也。自反之復，在人為德之本，故名下震上坤之卦曰「復」。其義震小而辯於坤之物，人則以此復卦之義而自知。愛人不親反其仁，治人不治反其智，禮人不答反其敬，惟自知反己，不責人之不親、不治、不答也。常久之恆，在人為德之固，故名上震下巽之卦曰「恆」。其義震之雷雜，而巽之風不厭，人則以此恆卦之義而一德。一，謂終始如一也。減省之損，在人為德之修，故名下兌上艮之卦曰「損」。其義：先損兌之澤難，而後成艮之山易，人則以此損卦之義而遠害。為不善者有害於已，減損其不善，所以遠去其害也。增多之益，在人為德之裕，故名上巽下震之卦曰「益」。其義巽之風長裕，而震之類不設，人則以此益卦之義而興利。為善者有利於已，增益其善，所以興起其利也。阨窮之困，在人為德之辯，故名上兌下坎之卦曰「困」。其義兌窮而坎通，人則以此困卦之義而寡怨。知命安分者，雖阨窮患難而無怨，寡之以至於無也。掘地得泉之井，在人為德之地，故名下巽上坎之卦曰「井」。其義：巽居其所而坎遷，人則以此井卦之義而辯義。已之惠澤及人者，義也。柔順卑下以入之巽，在人為德之制，故羲皇三畫之卦名「巽」，文王名六畫之重卦亦曰「巽」。其義：上中二陽宜稱於外，而下之一陰隱伏於內，人則以此重巽之義而行權。行，謂不定在一處。權者，稱錘，前卻無定，以等物之輕重而取衡之平，時中是也。六十四卦，其可以處憂患者不止於九，夫子姑舉其大槩爾。五十六重卦，舉八卦，七之一也；純卦舉一卦，八之一也。</p><p>傳六之四章，凡百四十五字。厭：因劍切。易：以豉切。長：知兩切。稱：充證切。行：下孟切。遠：於願切。注「充長」同上。疢：充震切。尤處：充許切，後一處同。鄉原音願。閹音淹。橫逆：封孟切。時復：符後切。畚音本。以上時掌切，後「而上」同。揠音戛切。涸：曷各切。而說：音曰。減省所梗切。安分：奉問切。難：乃旦切。掘：群厥切。錘：程追切。 易之為書也不可遠，為道也屢遷。 不可遠，謂其書之利於民用，不可離去也。屢遷，謂其變易不一定也。 變動不居，周流六虛，上下無常，剛柔相易，不可為典要，唯變所適， 以卦變言也。變動，謂卦畫更變移動，兩易其位也。不居，不止定在一處也。周流，周徧流行也。六虛，卦之六位也。在上位者或降而下，在下位者或升而上，無有常處者，以剛柔二畫之互相易也。典要，典籍中之契要，常而不可易者也。不可為典要，謂其易而不可常也。唯其變畫之所之，適在何位爾。案：傳之單言變者，謂蓍策之變；言變化者，謂卦畫之變。唯變所適，非謂蓍策也。而亦單言變者，蓋此言卦變之互易其位，非爻變之變化其畫也。不可言化，故亦單言變。夫子於彖傳已言卦變矣，而於此又言之。一體三畫自相易者，「復」、「姤」、「臨」、「遁」、大壯、「觀」、「夬」、「剝」所變也。下體三畫與上體三畫互相易者，「泰」、「否」、「坎」、「離」、「震」、「艮」、「巽」、「兌」所變也。蔡氏曰：「此言易道之屢遷也。」 其出入以度，外內使知懼，又明於憂患與故，無有師保，如臨父母。 「出入以度，外內知懼」，言人事之動，亦當如卦畫之變也。出，謂升上。入，謂降下。外者，上也。內者，下也。卦畫之出而外、入而內者，皆以其度，或一體自易，或二體互易。六子八辟之所變各二卦，泰、否二闢之所變各九卦，如度之分寸，各有界限，不可僭差。人事之或出或入，亦必如卦畫之出入，以度其出入，動循禮法，使出而在外、入而在內之時，惕然知所畏懼。此聖人作易訓人之意。使，謂聖人之使人如此也。凡人之出入，能明於聖人之憂患與民同之義，以慎乃事而守之嚴，雖無有師保顯為之教戒，而畏懼不敢慢易，惕然一如父母之臨其上也。蔡氏曰：「此言易書之不可遠也。」 初率其辭而揆其方，既有典常，苟非其人，道不虛行。 「初」，始也。率，循也。辭，彖、爻之辭也。揆，度也。方，所向也。既，盡也。典常，典籍中所載之常法，一定而不可易者也。言人於用易之始，循易書之辭，而揆其處事之方，其道盡有常法，不可變易也。上言卦畫之變，其道變而不常；此言彖爻之辭，其道常而不變也。苟，猶若也。其人，謂聖人。易之道雖如此，若非作易之聖人示此道以教人，則易之道不能無人而自行也。蓋言易道之行於世者，皆聖人之功。蔡氏曰：此合書與道為言也。</p><p>傳六之五章，凡八十三字。要，去聲。度，如字。注並同注。離，艮智切。更變，音庚。一處、常處，充注切。闢，音壁。慢易，以豉切。度也，待洛切。處事，昌主切。 易之為書也，原始要終，以為質也。六爻相雜，唯其時物也。 要，如「要於路」之「要」，謂遮截其歸宿之處。質，謂卦之體質。文王原卦義之始，要卦義之終，以為卦之體質，各名其卦而系彖辭也。爻之為言交也，六位之陰陽相雜而交錯也。時，謂初、二、三、四、五、上之時。物，謂陽奇、陰耦二畫之物。周公觀六爻之交錯，唯其六位之時，或是陽物，或是陰物，各因其義而系爻辭也。此章言六爻，而六爻統於彖，故先言彖。下文乃分說六爻也。 其初難知，其上易知，本末也。初辭擬之，卒成之終。 此言初、上二爻。侯氏果曰：初則事微，故難知；上則事彰，故易知。澄謂初如木下之本，上如木上之末。觀木者，其下之本根難見，其上之枝葉易見也。項氏曰：初禍福未定，故其辭多擬議；上已睹其成，禍福判矣，故其辭多決定。澄案：終謂上爻、初爻之辭。「擬之」者，猶有商度。卒竟成完而言之者，終爻之辭也。「初」與「終」為對，「擬之」與「卒成之」為對，兩句文法顛倒相互。 若夫雜物撰德，辯是與非，則非其中爻不備。 此言卦中四爻。中爻謂二、三、四、五也。朱子曰：先儒多解此為互體。胡氏一桂曰：「雜物」謂陰陽一物，自中四爻雜而互之，又自撰成兩卦之德也。是與「非」，謂中與不中、當位與不當位也。內外卦既足以示人，復自互體而辯之，則是非益可見。澄謂內外既有二正體之卦，中四爻又成二互體之卦，然後其義愈無遺缺。非以此正體、互體並觀，則其義猶有不備。正體則二為內卦之中，五為外卦之中；互體則三為內卦之中，四為外卦之中，故皆謂之中爻。 噫！亦要存亡吉凶，則居可知矣。知者觀其彖辭，則思過半矣。 上文既分言初、上二爻及中四爻，此又總六爻言之。存亡者，陰陽之消息；吉凶者，事情之得失。居，猶坐也。要其存亡吉凶之所歸，則六爻之義坐而可知矣。又謂知者能見事於未形，雖不觀各爻之義，但觀卦首之彖辭，則所思已得十分之五六矣。蓋彖辭或論二體，或論主爻，或論卦變相易之爻，是以不待觀六爻而已可見也。章首第一句言彖，第二句總言六爻，此一節又總言六爻，而後歸重於彖，蓋為結語，與章首起語相始終。下文則又更端而言中四爻也。 二與四，同功而異位，其善不同，二多譽，四多懼，近也。柔之為道，不利遠者，其要無咎，其用柔中也。 二與四同是陰位，若皆以柔居之，則六二、六四，同是以柔居陰，故曰「同功」。然其位則有遠近之異。五者，一卦之尊位，故遠近皆自五而言。二與五應為遠，四與五比為近。以位之遠近有異，而其善亦不同。遠者，意氣舒展而多譽；近者，勢分逼迫而多懼。多者，謂不盡然，而若此者眾爾。「近也」二字，釋「四」。「多懼」，謂四之所以懼，不能如二之譽者，蓋迫近尊位，不得自安故也。「柔之為道」以下，釋「二」。多譽。柔不能自立，近者有所依倚，遠者宜若不利。二遠於五，而其歸得以無咎者，以其用柔而居下卦之中也。 三與五，同功而異位。三多兇，五多功，貴賤之等也。其柔危，其剛勝邪？ 三與五同是陽位，若皆以剛居之，則九三、九五同是以剛居陽，故曰「同功」。然其位則有貴賤之異。五，天子之位，為貴；三，諸侯之位，為賤。以位之貴賤有異，賤者剛居剛，為大過而多兇，貴者剛居剛為適宜而多功。「二多譽」、「四多懼」之上有「其善不同」一句，而「三多兇」、「五多功」之上無之者，譽懼雖不同，而皆可謂之善，兇則不可謂善矣，故不言也。等，謂兩相比並而有品級。「貴賤之等也」，五字釋「三多兇」，謂三之所以兇，不能如五之功者，蓋貴賤有等，賤者不與貴者同，不宜以剛居剛故也。「其柔危」以下，釋「五多功」。五為尊位，以柔居之，則不勝其任而危，惟剛居之，則能勝其任而有功也。</p><p>傳六之六章，凡百四十四字。要，一遙切。後同。易知，以豉切。夫，音扶。撰，士免切。知者，音智。思，先次切。勝，音升。注摘度，待洛切。竟，音敬。復自，符後切。五比，皮二切。勢分符問切。 易之為書也，廣大悉備。 廣，謂如地之無所不容；大，謂如天之無所不包。悉備，謂人物之理纖悉具備於其中。 有天道焉，有人道焉，有地道焉。 此言三畫之卦。「天道」，謂上畫象大覆於上。「人道」，謂中畫象悉備於中。「地道」，謂下畫象廣載於下。 兼三才而兩之，故六，六者非他也，三才之道也。 此言六畫之卦。「兼」，猶言雙也。一手持二秉曰「兼」。三畫之卦象三才，三才各一而已。一而不兩，則獨而無對，天獨陽而無陰，地獨陰而無陽，人之陰陽亦混而不分，必皆兼而兩之，天、人地各有陰陽，然後其道全而不偏，所以重三畫之卦而為六畫者，此也。有六畫，則初、二為「地道」，三、四為「人道」，五、上為「天道」，各兩其一而為六，六者非有他也，以三才之道各有陰陽也。 道有變動，故曰爻，爻有等，故曰物，物相雜，故曰文，文不當，故吉凶生焉。 「道」，即上文所謂「天道」、「人道」、「地道」也。「有變動」，謂卦位之為天、為人、為地者，有更變移動也。三畫之卦重為六畫，惟初為地道，上為天道，不改移，中四畫皆有改移。二，人也，而為地。三，天也，而為人。四，地也，而為人。五，人也，而為天。故曰「道有變動」。陰位陽位交錯相間，謂之「爻」。三畫之卦不曰「爻」者，無陰陽相間也。既有六畫，而三才之道改移其位，然後初為地之陽，二為地之陰，三為人之陽，四為人之陰，五為天之陽，上為天之陰，相交錯而謂之爻也。等，如上章貴賤之等。各爻之畫比並有不同，故曰有等。其有等不同者，或是奇畫，則為陽物，或是耦畫，則為陰物也。二物相雜在六位之中，然後成文。若陰陽純而不雜，則不文矣。文不當，謂陽物居陰位，陰物居陽位，當位者多吉，不當位者多兇，吉凶由當不當而生，不言當而但言不當者，省文自可見意也。</p><p>傳六之七章，凡六十六字注覆，孚後切。間，居限切，下同。省文，所梗切。 易之興也，其當殷之末世、周之盛德邪？當文王與紂之事邪？ 殷之末世，謂紂。周之盛德，謂文王。因第四章之起語而申言之，彼但言其時，此並言其人也。此卒章之第一節。 是故其辭危。危者使平，易者使傾，其道甚大，百物不廢，懼以終始，其要無咎，此之謂易之道也。 是故以下，終第一節之意。危者，懼而不敢安也。易者，匆而不知懼也。文王以盛德遇末世而有憂患，故其系易也，有危懼之辭，蓋謂人之處事，其心危懼則可保平康，其心匆易則必至傾覆。使者，理有必至，若或使之云爾。前篇以「易則易知」言乾之善，此章又以「易者使傾」言人之惡。易知之易，敬勝怠而其心易直也；使傾之易，怠敬勝而其心匆易也。字雖同而其意正相反。「其道」，謂作易之道。物，猶事也。不廢，謂具備於中而無所棄遺也。易之道，雖無一事不該，然不過欲人於每事自始至終以危懼之心處之，其指歸欲人之無咎而已。易有彖辭，有爻辭，而所謂「其辭危」者，乃專以文王彖辭言，何也？蓋繫辭自文王始，周公不過補文王之未及為者爾，無異旨也。父統子葉，但言彖辭，而爻辭在其中矣。下文則皆兼彖、爻之義而言也。 夫乾，天下之至健也，德行恆易以知險。夫坤，天下之至順也，德行恆簡以知阻。能說諸心，能研諸慮，定天下之吉凶，成天下之亹亹者， 言聖人作易之道，本乎天地也。乾坤謂天地，非卦名也。天之健，地之順，造化流行，常易常簡，無有繁難也，又豈有妨害之者？而天地猶且知險知阻，人事則不無妨害之虞，其可匆易而不危懼乎？天地之知險知阻，非如人之知也。天之下，凡有險陷之處，天皆臨而照之，是天下之險，天無一不知也。地之上凡有阻礙之處，地皆載而有之，是地上之阻，地無一不知也。作易聖人能如天之知險，故凡可以陷害於人者，必為之指示，以通其志，使人皆灼見，則其心開釋而說懌。能如地之知阻，故凡可以妨礙於人者，必為之處置，以成其務，使人皆慎行，則其慮精審而研核定其所佔之如是則吉，如是則兇，使人之於事無疑有決，而勉勉為之也。此第二節。 是故變化云為，吉事有祥，象事知器，佔事知來。天地設位，聖人成能，人謀鬼謀，百姓與能。 「是故」以下，終第二節之意。「云為」，言動也。人能以易中陰陽變化之道，而用之以言，用之以動，則於事皆可以旨而有祥，必不至於兇而有災也。或有所象之事，則能知器之形，而可以制器；或有所佔之事，則能知未來之吉凶，而可以決疑。易之用，惟此四者而已。「云為」、「象佔」，即上篇所謂「以言」、「以動」、「以制器」、「以卜筮」也。此四者，皆聖人本諸天地之道以教人者。故「天地設位於上下」，雖有此道，而不能使悉由此道。聖人作易，教人由此道，所以成天地之能也。「成」，謂有所闕而完足之。「鬼謀」，謂覡巫。「與」，如中庸「可以與知焉」之「與」。「人謀」，羲文之易，而用之以佔。凡有一事，既謀之於人，又謀之於鬼，而後為之，則所為皆合易道之教，雖其愚不肖，亦可以與聖人之能也。健順易簡，知險知阻，此天地之能。說心研慮，定吉凶，成亹亹，此聖人之能，而成天地之能也。雲「為之祥」，象佔之知，此百姓之能，而與聖人之能者也。 八卦以象告，爻彖以情言。剛柔雜居，而吉凶可見矣。變動以利言，吉凶以情遷。 八卦，謂六爻、四象之上下二體也。項氏曰：「八卦以象告」，謂卦之以四象示人。「爻彖以情言」，謂辭之以言諭人也。「剛柔雜居而吉凶可見」，再言象之所以示人者明也。「變動以利言，吉凶以情遷」，再言辭之所以諭人者殊也。自彖辭觀之，卦體本以變動而成，故彖辭專言其變動之利，如「柔來而文剛」，「分剛上而文柔」之類是也。雖睽、蹇、明夷至不美之卦，其彖皆有所利，蓋類變而成卦，則以成卦者為利，故曰「變動以利言」。自爻辭觀之，據逐爻之情而處事，則吉凶皆異於本彖矣。故有在彖為主爻，而在本爻則為兇者，如震之九四，「震驚百里」，可為祭主，而在本爻則為「泥而未光」之類是也。故曰「吉凶以情遷」，觀彖之本辭，則為遷易也。澄謂：「變動即第五章所謂變動不居者，言卦畫之更變移動其位也。爻彖以情言，彖與爻皆言情也。吉凶以情遷，則情專屬爻而不及彖，何也？蓋變動以利言，利亦自情而生也。彖亦有情，爻亦有利，互文也。」此第三節。 是故愛惡相攻而吉凶生，遠近相取而悔吝生，情偽相感而利害生。凡易之情，近而不相得則兇；或害之，悔且吝。 「是故」以下至篇終，皆終第三節之意。「愛惡」者，情也。「相攻」，謂相愛兩相惡也。「遠」，謂應；「近」，謂比。「相取」，謂遠取遠、近取近也。情之真者曰情，情之非真者曰「偽」。「相感」，謂情感情、偽感偽也。愛惡遠近皆有情偽，或以情相取，或以偽相取。情偽皆有愛惡，其相愛或真或偽，其相惡亦或真或偽。偽者，情之反；害者，利之反。凡佔曰「不利」、「無攸利」者，害也。項氏曰：「自此以下，皆言吉凶以情遷之事。以六爻吉凶悔吝之三辭，分出於相攻、相取、相感之三情，而總屬於相近之一情。四相者，爻之情也。命辭之法，必各象其爻之情，故觀其辭可以知其情。利害者，商略其事宜，有利有不利也。悔吝則有跡矣，言兇則其成也，故總而名之曰吉凶。」「相感」者，情之始交，故以「利害」言之；「相取」則有事矣，故以「悔吝」言之；「相攻」則其事極矣，故以「吉凶」言之。「遠近」「情偽」，姑就淺深分之，若錯而總之，則「相攻」「相取」「相感」之人，其意皆有遠近，其行皆有情偽，其情皆有愛惡也，故總以「相近」一條明之。「近而不相得」，則以「惡相攻」而兇生矣，以「偽相感」而害生矣，不以「近相取」而悔吝生矣，是則一近之中備此三條也。凡爻有比爻，有應爻，有一卦之主爻，皆情之當相得者也。凡稱近者，止據比爻言之，反以三隅，則遠而為應為主者，亦必備此三條矣。但居之近者，其吉凶尤多，故聖人槩以「近」者明之。近而不相得，則惡相攻、偽相感；近不相取則愛相攻、情相感，而近取者為相得矣。不相得則兇害悔吝，其相得則吉利悔亡，無悔無咎，從可知也。夫子之己言者三，其未言者三，總之凡六條。然此據近之比爻言爾，若遠之應爻及主爻，亦當各備六條，總之為十八條矣。嘗以此十八條之例考之爻辭皆合，乃知作傳聖人以此該括易之辭情，至為精密。而諸家註釋，唯項氏能究其底蘊焉。 將叛者其辭慚，中心疑者其辭枝，吉人之辭寡，躁人之辭多，誣善之人其辭遊，失其守者其辭屈。 上章言易之辭皆由情而生，此又以人譬之。人之辭亦由情而生也。將欲倍畔，猶未發露，中有所慊，唯恐為人所覺，故其辭慚怍；中心疑惑，不能剖決，意謂如此又恐不如此，故其辭如木之枝，兩閒端岐，不敢執一。吉人靜重深厚，故其辭謹而簡；躁人輕動淺薄，故其辭易而繁；誣毀善人自知非實，故其辭浮游不定；困阨沮喪，失所操守，故其辭卑屈不伸。叛、疑、吉、躁、誣、失者，人之六情有不同，故慚、枝、寡、多、遊、屈，其六辭各因其情而不同焉。朱子曰：卦爻之辭亦猶是也。澄案：此篇之首章，泛言辭變象佔四道，而末句歸重於辭，且以本於聖人之情。至此卒章凡三節，其中亦言四道，而首末皆言彖爻之辭，末又本於易之情，以終繋辭之傳。蓋唯聖人之情能知易之情而系易之辭也。是為一篇始終之脈絡雲。</p><p>傳六之八章，凡二百五十四字。「研諸」下，舊本有「侯之」二字，案王氏略例無之。晁氏曰：「王昭素、司馬溫公皆以為衍字。」易者，恆易，以豉切。要，一遙切。夫，音扶。行，下孟切。說，音曰。與能，音預。惡，烏路切。注「必為之」，雲偽切。與，如字。與知之與、與於而與，並音預。比，皮二切。繫辭傳上下篇，共二十章，章首發端以天地字者三，以聖人字者二，以易字者卜一，以彖爻，以一陰一陽，以八卦，以陽卦、陰卦者各一。舊本有「子曰」者六，先儒以為後人所加。今考之，「易，其至矣乎！知變化之道者，其知神之所為乎？」皆是前章之結語，後之分章者欲以此為後章之起語。「書不盡言」，「乾坤其易之門邪」，皆是連上文「共」為一章，後之分章者欲分截自此別為一章，故四處各加「子曰」字以別之。易有聖人之道四馬者，是再提章首起句為結句，聖人立象以盡意，是以答語答上文問語，故兩處亦各加「子曰」字，今並刪去，庶俾讀者不致生疑，而妄謂繫辭傳非夫子所作雲。 易纂言卷八。</p>',12)])])}const m=e(n,[["render",r]]);export{f as __pageData,m as default};
